render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(a = cfg$x, b = cfg$y, c = cfg$group, value = cfg$size), c("a", "b", "c", "value")); data$.mynx_a <- data[[cfg$x]]; data$.mynx_b <- data[[cfg$y]]; data$.mynx_c <- data[[cfg$group]]; data$.mynx_value <- data[[cfg$size]]; p <- ggplot2::ggplot(data, ggplot2::aes(axis1 = .mynx_a, axis2 = .mynx_b, axis3 = .mynx_c, y = .mynx_value)) + ggalluvial::geom_alluvium(ggplot2::aes(fill = .mynx_a), alpha = 0.7) + ggalluvial::geom_stratum(fill = "#E2E8F0", colour = "#64748B") + ggplot2::geom_text(stat = "stratum", ggplot2::aes(label = ggplot2::after_stat(stratum)), size = 3) + ggplot2::scale_x_discrete(limits = c("阶段 1", "阶段 2", "阶段 3"), expand = c(.08, .08)) + ggplot2::theme_minimal(base_size = 12) + ggplot2::theme(axis.title = ggplot2::element_blank()) + ggplot2::labs(title = cfg$title %||% NULL); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
